// Python's repr() for the value shapes this program prints.

import { PyBytes } from './bytes.mjs';
import { isPrintable } from '../unicode/properties.mjs';

// repr prefers single quotes, switching to double only when that avoids
// escaping — i.e. when the value contains ' but no ".
function pickQuote(hasSingle, hasDouble) {
  return hasSingle && !hasDouble ? '"' : "'";
}

// The only mnemonic escapes repr emits. Notably \v, \f, \a and \b are *not*
// among them; those fall through to \xHH.
const MNEMONIC_ESCAPES = new Map([
  [0x5c, '\\\\'],
  [0x09, '\\t'],
  [0x0a, '\\n'],
  [0x0d, '\\r'],
]);

function hexEscape(codePoint) {
  if (codePoint < 0x100) return `\\x${codePoint.toString(16).padStart(2, '0')}`;
  if (codePoint < 0x10000) return `\\u${codePoint.toString(16).padStart(4, '0')}`;
  return `\\U${codePoint.toString(16).padStart(8, '0')}`;
}

export function reprBytes(value) {
  const { codes } = value;
  const quote = pickQuote(codes.includes(0x27), codes.includes(0x22));
  const quoteCode = quote.charCodeAt(0);
  let out = `b${quote}`;
  for (const code of codes) {
    const mnemonic = MNEMONIC_ESCAPES.get(code);
    if (mnemonic !== undefined) out += mnemonic;
    else if (code === quoteCode) out += `\\${quote}`;
    else if (code < 0x20 || code >= 0x7f) out += hexEscape(code);
    else out += String.fromCharCode(code);
  }
  return out + quote;
}

export function reprStr(text) {
  const quote = pickQuote(text.includes("'"), text.includes('"'));
  let out = quote;
  for (const ch of text) {
    const codePoint = ch.codePointAt(0);
    const mnemonic = MNEMONIC_ESCAPES.get(codePoint);
    if (mnemonic !== undefined) out += mnemonic;
    else if (ch === quote) out += `\\${quote}`;
    else if (!isPrintable(ch)) out += hexEscape(codePoint);
    else out += ch;
  }
  return out + quote;
}

export function reprInt(value) {
  return String(value);
}

// Containers delegate to repr for their members, exactly as Python does.
export function pyRepr(value) {
  if (value instanceof PyBytes) return reprBytes(value);
  if (typeof value === 'bigint') return reprInt(value);
  if (typeof value === 'string') return reprStr(value);
  if (Array.isArray(value)) return `[${value.map(pyRepr).join(', ')}]`;
  if (value instanceof Map) {
    const entries = [];
    for (const [key, item] of value) entries.push(`${pyRepr(key)}: ${pyRepr(item)}`);
    return `{${entries.join(', ')}}`;
  }
  if (value === null) return 'None';
  if (value === true) return 'True';
  if (value === false) return 'False';
  return String(value);
}

