// Generate fuzz cases for the "bytes-repr" dimension.
import { writeFileSync } from 'node:fs';

const cases = [];
const add = (name, a, b = '5') => cases.push({ name, argv: ['--a', a, '--b', b] });

const ch = (c) => String.fromCharCode(c);

// ---- 1. Every ASCII byte 0x01..0x7f as the sole --a value -----------------
for (let c = 0x01; c <= 0x7f; c += 1) {
  add(`sole-0x${c.toString(16).padStart(2, '0')}`, ch(c));
}

// ---- 2. Every ASCII byte embedded among other characters ------------------
for (let c = 0x01; c <= 0x7f; c += 1) {
  add(`mid-0x${c.toString(16).padStart(2, '0')}`, `A${ch(c)}Z`);
}

// ---- 3. Every ASCII byte doubled + repeated, at edges ---------------------
for (let c = 0x01; c <= 0x7f; c += 4) {
  const h = c.toString(16).padStart(2, '0');
  add(`lead-0x${h}`, `${ch(c)}tail`);
  add(`trail-0x${h}`, `head${ch(c)}`);
  add(`triple-0x${h}`, ch(c).repeat(3));
}

// ---- 4. Quote presence combinations --------------------------------------
const quoteCases = [
  ['q-none', 'plain'],
  ['q-single', "it's"],
  ['q-double', 'say "hi"'],
  ['q-both', `mix ' and "`],
  ['q-both-rev', `mix " and '`],
  ['q-only-single-1', "'"],
  ['q-only-single-2', "''"],
  ['q-only-single-many', "'''''"],
  ['q-only-double-1', '"'],
  ['q-only-double-2', '""'],
  ['q-only-double-many', '"""""'],
  ['q-both-1-1', `'"`],
  ['q-both-1-1-rev', `"'`],
  ['q-many-single-one-double', `'''''"`],
  ['q-one-single-many-double', `'"""""`],
  ['q-many-each', `'''""" ''' """`],
  ['q-adjacent', `''""''""`],
  ['q-single-then-double-far', `'${'x'.repeat(20)}"`],
  ['q-double-then-single-far', `"${'x'.repeat(20)}'`],
  ['q-triple-single', "'''"],
  ['q-triple-double', '"""'],
  ['q-single-in-double', `"it's"`],
  ['q-double-in-single', `'say "x"'`],
];
for (const [n, a] of quoteCases) add(n, a);

// ---- 5. Backslash runs of length 1..5, alone and combined ----------------
for (let n = 1; n <= 5; n += 1) {
  add(`bs-run-${n}`, '\\'.repeat(n));
  add(`bs-run-${n}-mid`, `a${'\\'.repeat(n)}b`);
  add(`bs-run-${n}-lead`, `${'\\'.repeat(n)}b`);
  add(`bs-run-${n}-trail`, `a${'\\'.repeat(n)}`);
  // backslash immediately before a quote
  add(`bs-${n}-before-sq`, `${'\\'.repeat(n)}'`);
  add(`bs-${n}-before-dq`, `${'\\'.repeat(n)}"`);
  add(`bs-${n}-before-both`, `${'\\'.repeat(n)}'${'\\'.repeat(n)}"`);
  add(`bs-${n}-after-sq`, `'${'\\'.repeat(n)}`);
  add(`bs-${n}-after-dq`, `"${'\\'.repeat(n)}`);
}
add('bs-escape-lookalikes', '\\n\\t\\r\\x41\\\\');
add('bs-x-hex', '\\x27\\x22\\x5c');
add('bs-u', '\\u0041\\U00000041');
add('bs-mixed-quotes', `\\'\\"`);

// ---- 6. Mnemonic vs hex control characters -------------------------------
const ctrl = [
  ['ctrl-tab', '\t'],
  ['ctrl-nl', '\n'],
  ['ctrl-cr', '\r'],
  ['ctrl-vt', '\v'],
  ['ctrl-ff', '\f'],
  ['ctrl-bel', '\x07'],
  ['ctrl-bs', '\b'],
  ['ctrl-esc', '\x1b'],
  ['ctrl-del', '\x7f'],
  ['ctrl-all-mnemonic', '\t\n\r\\'],
  ['ctrl-all-nonmnemonic', '\x07\b\v\f'],
  ['ctrl-mixed', 'a\tb\nc\rd\ve\ff\x07g\bh'],
  ['ctrl-crlf', '\r\n'],
  ['ctrl-lfcr', '\n\r'],
  ['ctrl-nl-with-quote', "line1'\nline2"],
  ['ctrl-nl-with-dquote', 'line1"\nline2'],
  ['ctrl-low-sweep', '\x01\x02\x03\x04\x05\x06\x07\x08\x09\x0a\x0b\x0c\x0d\x0e\x0f'],
  ['ctrl-low-sweep2', '\x10\x11\x12\x13\x14\x15\x16\x17\x18\x19\x1a\x1b\x1c\x1d\x1e\x1f'],
  ['ctrl-space-boundary', '\x1f \x20!'],
  ['ctrl-7e-7f', '~\x7f'],
];
for (const [n, a] of ctrl) add(n, a);

// ---- 7. Strings that are themselves valid bencode ------------------------
const bencodeish = [
  'i5e', 'i0e', 'i-1e', 'ie', 'i', 'e',
  'l4:teste', 'le', 'l', 'lll',
  '3:abc', '0:', '1:a', '10:abcdefghij',
  'd1:ai1ee', 'de', 'd',
  'l5:helloi5eli5eee',
  "b'l5:helloi5eli5eee'",
  'li5eli5eee', 'lli5eee',
  '4:test', '4:tes', '4:testx',
  'i9999999999999999999e',
  'd3:foo3:bare',
  'd1:al1:be1:ci1ee',
  'l3:onel3:twoee',
  '2:i5', 'i5', '5e', ':5',
  'llllllllleeeeeeeee',
  'd0:0:e',
  'i5ei6e', '3:abc3:def',
];
for (const a of bencodeish) add(`bencode-${JSON.stringify(a)}`, a);

// ---- 8. Length-prefix width transitions ---------------------------------
for (const len of [0, 1, 8, 9, 10, 11, 98, 99, 100, 101, 998, 999, 1000, 1001]) {
  add(`len-${len}-x`, 'x'.repeat(len));
  add(`len-${len}-quote`, len === 0 ? '' : "'".repeat(len));
  add(`len-${len}-bs`, len === 0 ? '' : '\\'.repeat(len));
}
// lengths where escaping changes the *rendered* length but not the prefix
for (const len of [9, 10, 99, 100]) {
  add(`len-${len}-nl`, '\n'.repeat(len));
  add(`len-${len}-mixq`, ("'" + '"').repeat(Math.floor(len / 2)));
}

// ---- 9. Interaction with --b (affects the rest of the repr) --------------
for (const b of ['5', '0', '-1', '-999', '10', '99', '100', '1000', '2147483648',
                 '99999999999999999999', '-99999999999999999999']) {
  add(`b-${b}-simple`, 'abc', b);
  add(`b-${b}-quote`, "a'b", b);
  add(`b-${b}-dquote`, 'a"b', b);
}

// ---- 10. Printable ASCII sweep in chunks (checks no over-escaping) -------
let sweep = '';
for (let c = 0x20; c <= 0x7e; c += 1) sweep += ch(c);
add('sweep-printable-all', sweep);
add('sweep-printable-noquotes', sweep.replace(/['"]/g, ''));
add('sweep-printable-nosingle', sweep.replace(/'/g, ''));
add('sweep-printable-nodouble', sweep.replace(/"/g, ''));
for (let i = 0; i < sweep.length; i += 16) {
  add(`sweep-chunk-${i}`, sweep.slice(i, i + 16));
}
// full 0x01..0x7f in one value
let full = '';
for (let c = 0x01; c <= 0x7f; c += 1) full += ch(c);
add('sweep-all-0x01-0x7f', full);
add('sweep-all-nosingle', full.replace(/'/g, ''));
add('sweep-all-nodouble', full.replace(/"/g, ''));
add('sweep-all-noquotes', full.replace(/['"]/g, ''));

// ---- 11. Digits/colon confusion in the encoded stream --------------------
const digitish = [
  '5:5', '999', '0', '00', '000000000', 'e5', '5e5',
  '1:1:1:1', ':::', '::::::::::',
  '12345678901234567890',
  '-5', '+5', ' 5 ',
];
for (const a of digitish) add(`digit-${JSON.stringify(a)}`, a);

writeFileSync('/tmp/cases-bytesrepr.json', JSON.stringify(cases, null, 0));
console.log(`generated ${cases.length} cases`);

